describe('Notification Message Rendered', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
  });

  it('should display notification with success message after clicking "Click here" link', () => {
    // Verify initial page state
    cy.get('#content').should('be.visible');
    cy.get('#page-footer').should('contain', 'Footer');

    // Click the "Click here" link
    cy.get('[data-testid="Click here"]').click();

    // Verify flash element appears
    cy.get('#flash-messages').should('be.visible');
    cy.get('#flash-messages').should('contain', 'Action successful');

    // Verify close icon is present
    cy.get('#flash-messages').should('contain', '.close');

    // Verify notification text is displayed
    cy.get('#flash-messages').should('contain', 'Action successful');

    // Verify close icon works
    cy.get('#flash-messages').click();
    cy.get('#flash-messages').should('not.exist');
  });

  it('should display error notification with unsuccessful message when action fails', () => {
    // Verify initial page state
    cy.get('#content').should('be.visible');
    cy.get('#page-footer').should('contain', 'Footer');

    // Click the "Click here" link
    cy.get('[data-testid="Click here"]').click();

    // Verify flash element appears
    cy.get('#flash-messages').should('be.visible');

    // Verify error message is displayed
    cy.get('#flash-messages').should('contain', 'Action unsuccessful');

    // Verify close icon is present
    cy.get('#flash-messages').should('contain', '.close');

    // Verify notification text is displayed
    cy.get('#flash-messages').should('contain', 'Action unsuccessful');

    // Verify close icon works
    cy.get('#flash-messages').click();
    cy.get('#flash-messages').should('not.exist');
  });
});
